using System;
using System.Linq;
using EmberBastion;
class ReinforcementCombatChecks {
 static int checks;static void Check(bool ok,string label){checks++;if(!ok)throw new Exception(label);}
 static void WaitForCall(Battle b){for(int n=0;n<100000&&!b.CanCallEarly()&&b.Phase==Phase.Fighting&&!b.ReinforcementPending;n++)b.Step(1.0/60);Check(b.CanCallEarly(),"early call reachable at wave "+b.Wave);}
 static void Main(){
  var b=new Battle(42);Check(b.EnableReinforcements(),"enable");Check(!b.SetDifficulty(2)&&b.FastWaves&&!b.HardWaves,"difficulty locked");var prep=Battle.RestorePreparation(b.SavePreparation());Check(prep.Reinforcements!=null&&prep.Reinforcements.SelectedCount==0,"prep roundtrip");b.Gold=10000;for(int i=0;i<b.Field.Slots.Length;i++)Check(b.Place(i%3,i),"place");Check(b.Start(),"start");
  for(int goal=3;goal<=6;goal+=3){while(b.Wave<goal&&!b.ReinforcementPending){WaitForCall(b);Check(b.CallEarly(),"call");}Check(b.Wave==goal-1&&b.ReinforcementPending,"offer before wave");double time=b.Time;int gold=b.Gold;Check(!b.Place(0,0)&&!b.Sell(0)&&!b.Upgrade(0)&&!b.Ember(new Point(500,300)),"no actions while choosing");b.Step(.25);Check(time==b.Time&&gold==b.Gold&&!b.CanCallEarly(),"simulation paused");var options=b.Reinforcements.Choices();var saved=b.ExportCombat();var restored=Battle.ImportCombat(saved);Check(restored.ReinforcementPending&&options.SequenceEqual(restored.Reinforcements.Choices()),"save roundtrip");var copy=b.CopyCombat();Check(options.SequenceEqual(copy.Reinforcements.Choices()),"checkpoint roundtrip");Check(!restored.ChooseReinforcement(7),"invalid rejected");Check(restored.ChooseReinforcement(options[0])&&restored.Wave==goal&&!restored.ReinforcementPending,"resume next wave");Check(b.ChooseReinforcement(options[0]),"choose original");Check(b.Wave==goal&&b.Reinforcements.SelectedCount==goal/3,"exactly one choice");}
  var automatic=new Battle(29);Check(automatic.EnableReinforcements(),"auto enable");automatic.Gold=10000;for(int i=0;i<automatic.Field.Slots.Length;i++)automatic.Place(i%3,i);Check(automatic.Start(),"auto start");int offers=0;automatic.ReinforcementOffered=x=>offers++;for(int i=0;i<30000&&!automatic.ReinforcementPending&&automatic.Phase==Phase.Fighting;i++)automatic.Step(1.0/60);Check(automatic.ReinforcementPending&&automatic.Wave==2&&offers==1,"automatic transition opens once");automatic.Step(.25);Check(offers==1,"automatic pending does not redraw");
  var ordinary=new Battle(17);ordinary.Place(0,0);ordinary.Start();var legacy=ordinary.ExportCombat();legacy.reinforcement=new ReinforcementDraftData{randomState=0,owned=new int[0],offered=new int[0]};Check(Battle.ImportCombat(legacy).Reinforcements==null,"Unity empty object remains ordinary mode");legacy.reinforcement.randomState=1;bool malformed=false;try{Battle.ImportCombat(legacy);}catch(ArgumentException){malformed=true;}Check(malformed,"partial reinforcement state rejected");
  var bad=b.ExportCombat();bad.reinforcement.offered=new[]{1,1,2};bool rejected=false;try{Battle.ImportCombat(bad);}catch(ArgumentException){rejected=true;}Check(rejected,"corrupt offer rejected");Console.WriteLine("PASS "+checks+" reinforcement wave, pending save, retry and validation checks");
 }
}
